args.sql:
SELECT DISTINCT d.haz_level, d.damagereport 
FROM transportation t 
JOIN disasterevents d ON t.transportdistref = d.distregistry;

SELECT t.delivery_metrics->'delivery_performance'->>'route_optimization_status' as route_status, COUNT(*) 
FROM transportation t 
GROUP BY t.delivery_metrics->'delivery_performance'->>'route_optimization_status';

SELECT COUNT(*) FROM transportation t
JOIN disasterevents d ON t.transportdistref = d.distregistry
JOIN coordinationandevaluation c ON d.distregistry = c.coord_dist_ref;
